def test_reorg_below_the_catch_up_block_before_the_first_live_run_stays_silent(tmp_path, ctl): """A reorg that replaces the catch-up block after the silent run committed: the silent run is repeated, pinned to the catch-up block, so a new-chain event up to there is never sent; an event after it is sent once.""" env = Env(tmp_path) env.go_live(only=("cu_a",)) env.start(only=("cu_a",), disabled=("cu_a",)) env.step() env.step() env.start(only=("cu_a",)) env.step() pinned = env.w.checkpoint()["block"] # the catch-up block: the checkpoint of the first step after the start env.step(mine=False) rec = env.rec("cu_a") mark = env.last_rowid() env.chain.reorg(pinned) # the catch-up block itself is replaced replayed = env.event("cu_a") # at the catch-up block's height on the new chain assert replayed == pinned env.chain.mine() after = env.event("cu_a") env.chain.mine() env.step() check = env.check("cu_a") assert env.w.checkpoint()["block"] > pinned keys = _keys(env.msgs(after=mark)) # behavioural assertion first (red without the repeat: the replayed event at the catch-up block is sent) > assert f"ev:{replayed}" not in keys and keys == [f"ev:{after}"], keys E AssertionError: ['ev:1005', 'ev:1006'] E assert ('ev:1005' not in ['ev:1005', 'ev:1006'])
