@pytest.mark.parametrize("cause", ["reenabled", "new"]) def test_live_alerts_of_another_check_are_sent_while_a_catch_up_fails(tmp_path, ctl, cause): env = Env(tmp_path) env.go_live(only=IDS if cause == "reenabled" else ("cu_a",)) if cause == "reenabled": env.start(only=IDS, disabled=("cu_b",)) env.level("cu_b", 1, 1) old = env.event("cu_b") env.step() mark = env.last_rowid() ctl["cu_b"]["fail"] = 3 env.start(only=IDS) a_events = [env.event("cu_a")] # page-worthy for A, in the step of B's (failing) silent run env.step() assert _keys(env.msgs("cu_a", after=mark)) == [f"ev:{a_events[0]}"] # sent in that step pinned = env.w.checkpoint()["block"] # B's catch-up block late_b, recs = None, [] for i in range(2): # B keeps failing; A keeps alerting a_events.append(env.event("cu_a")) if i == 0: late_b = env.event("cu_b") # B's event after its catch-up block: live for B env.step() assert _keys(env.msgs("cu_a", after=mark)) == [f"ev:{b}" for b in a_events] recs.append(env.rec("cu_b")) assert env.msgs("cu_b", after=mark) == [] assert [h for h in env.health() if "check-error" in h["text"] and "cu_b" in h["text"]] env.step() # B recovers: silent at its pinned block, then live at this block, in the same step # behavioural assertion first (red on the CP1 head: B's recovered run sends its disabled-period event) > assert sorted(_keys(env.msgs("cu_b", after=mark))) == sorted(["lv1", f"ev:{late_b}"]) E AssertionError: assert ['ev:1003', 'ev:1005', 'lv1'] == ['ev:1005', 'lv1'] E E At index 0 diff: 'ev:1003' != 'ev:1005' E Left contains one more item: 'lv1' E E Full diff: E [ E + 'ev:1003', E 'ev:1005', E 'lv1', E ]
