@pytest.mark.parametrize("seed", range(30)) def test_seeded_catchup_sweep(tmp_path, ctl, seed): """Random disable/enable restarts, events, level toggles, failing runs (exception or transport RpcError), plain restarts, same-block steps and reorgs of depth 1-4 (also during a catch-up), confirmations 0/2. The catch-up block is derived independently of the record: the checkpoint of the first step after the start that re-enabled the check (a restart in between keeps it). Invariants after every action, per check: - nothing is sent for it while it is disabled, in the step of its catch-up block, or while its catch-up record exists (D3, D4); the record's block, when set, equals the independently derived one; - no event at or below its catch-up block (the disabled period and the catch-up) is ever sent; - every canonical event of its kind after its catch-up block, up to its committed cursor, is sent (no missed page; a live alert of one check is never held by the other's catch-up); no incident sends `open` twice; - at most one open row per key.""" rnd = random.Random(seed) env = Env(tmp_path, confirmations=rnd.choice([0, 2])) env.go_live() enabled = {cid: True for cid in IDS} floor = {cid: env.w.phase()["history_block"] for cid in IDS} # events at or below are never sent armed: set[str] = set() # re-enabled, catch-up block not known yet (the next step's checkpoint) for _ in range(40): act = rnd.choice(["step", "step", "event", "level", "flip", "restart", "fail", "same", "reorg"]) mark = env.last_rowid() stepped = act in ("step", "event", "level", "fail", "same") if act == "step": env.step() elif act == "event": env.event(rnd.choice(IDS)) env.step() elif act == "level": env.level(rnd.choice(IDS), rnd.randrange(3), rnd.randint(0, 1)) env.step() elif act in ("flip", "restart"): if act == "flip": cid = rnd.choice(IDS) enabled[cid] = not enabled[cid] (armed.add if enabled[cid] else armed.discard)(cid) env.start(disabled=[c for c in IDS if not enabled[c]]) elif act == "fail": cid = rnd.choice(IDS) CTL[cid].update(fail=rnd.randint(1, 3), rpc=rnd.random() < 0.5) env.step() elif act == "same": env.step(mine=False) elif act == "reorg": fork = env.chain.number - rnd.randint(1, 4) # a reorg below a catch-up block after the first live run replays catch-up events live: the D17 limit # shared with the global path (handoff, new findings), excluded here if fork > env.start_block + 1 and all( env.rec(c) is not None or fork > floor[c] for c in IDS if enabled[c]): env.chain.reorg(fork) if rnd.random() < 0.5: env.event(rnd.choice(IDS)) env.chain.mine() env.step() stepped = True new = env.msgs(after=mark) for cid in IDS: mine_new = [m for m in new if m["check_id"] == cid] if stepped and cid in armed: # the step of its catch-up block floor[cid] = env.w.checkpoint()["block"] armed.discard(cid) assert not mine_new, (seed, act, cid, "catch-up step", _keys(mine_new)) rec = env.rec(cid) if enabled[cid] else None if rec is not None and rec.get("history_block") is not None: assert rec["history_block"] == floor[cid], (seed, act, cid, rec, floor[cid]) assert not (mine_new and (not enabled[cid] or rec is not None)), (seed, act, cid, _keys(mine_new)) sent = env.msgs(cid) > assert not [m for m in mine_new if m["ikey_"].startswith("ev:") and int(m["ikey_"][3:]) <= floor[cid]], \ (seed, act, cid, floor[cid], _keys(mine_new)) E AssertionError: (15, 'step', 'cu_b', 1024, ['ev:1019', 'lv2']) E assert not [{'rid': 22, 'key': 'cu_b-ev:1019-1026:open', 'created_at': 1800115200.0, 'severity': 'page', 'text': '\U0001f6a8 [PAGE] cu_b event at 1019 \u2014 test\nIncident: cu_b-ev:1019-1026', 'attempts': 0, 'next_attempt_at': 0.0, 'sent_at': 1800115200.0, 'delivery': 'telegram', 'last_error': None, 'check_id': 'cu_b', 'incident_id': 'cu_b-ev:1019-1026', 'kind': 'open', 'receipt': 'captured', 'ikey_': 'ev:1019'}]
