nd.choice(IDS) CTL[cid].update(fail=rnd.randint(1, 3), rpc=rnd.random() < 0.5) env.step() elif act == "same": env.step(mine=False) elif act == "reorg": fork = env.chain.number - rnd.randint(1, 4) # a reorg below a catch-up block after the first live run replays catch-up events live: the D17 limit # shared with the global path (handoff, new findings), excluded here if fork > env.start_block + 1 and all( env.rec(c) is not None or fork > floor[c] for c in IDS if enabled[c]): env.chain.reorg(fork) if rnd.random() < 0.5: env.event(rnd.choice(IDS)) env.chain.mine() env.step() stepped = True new = env.msgs(after=mark) for cid in IDS: mine_new = [m for m in new if m["check_id"] == cid] if stepped and cid in armed: # the step of its catch-up block floor[cid] = env.w.checkpoint()["block"] armed.discard(cid) > assert not mine_new, (seed, act, cid, "catch-up step", _keys(mine_new)) E AssertionError: (23, 'step', 'cu_b', 'catch-up step', ['ev:1016']) E assert not [{'rid': 5, 'key': 'cu_b-ev:1016-1020:open', 'created_at': 1800093600.0, 'severity': 'page', 'text': '\U0001f6a8 [PAGE] cu_b event at 1016 \u2014 test\nIncident: cu_b-ev:1016-1020', 'attempts': 0, 'next_attempt_at': 0.0, 'sent_at': 1800093600.0, 'delivery': 'telegram', 'last_error': None, 'check_id': 'cu_b', 'incident_id': 'cu_b-ev:1016-1020', 'kind': 'open', 'receipt': 'captured', 'ikey_': 'ev:1016'}]
